from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

wb = load_workbook('/root/data/workbook.xlsx', data_only=False, keep_vba=True, keep_links=True)
data = wb['Data']

# Print a grid for rows 18-26, cols A-L
r0, r1 = 18, 26
c0, c1 = 1, 12
print('=== Data sheet snapshot (rows 18-26, cols A-L) ===')
for r in range(r0, r1+1):
    row_vals = []
    for c in range(c0, c1+1):
        v = data.cell(row=r, column=c).value
        if v is None:
            s = ''
        else:
            s = str(v)
        if len(s) > 22:
            s = s[:19] + '...'
        row_vals.append(f'{get_column_letter(c)}{r}:{s}')
    print(' | '.join(row_vals))

# Try to locate year header row by searching first 60 rows for consecutive 2019-2023
TARGET = [2019, 2020, 2021, 2022, 2023]
found = []
for r in range(1, 61):
    for c in range(1, data.max_column-4):
        seq = [data.cell(row=r, column=c+i).value for i in range(5)]
        if seq == TARGET:
            found.append((r, c))

print('\n=== Locations of [2019..2023] consecutive ===')
for r, c in found[:20]:
    print(f'Row {r}, starting at {get_column_letter(c)}')
if not found:
    print('None found')

# Try to locate series codes by searching for one known code
needle = 'ATL_SUCCESS_REQ'
locs = []
for r in range(1, data.max_row+1):
    for c in range(1, data.max_column+1):
        if data.cell(row=r, column=c).value == needle:
            locs.append((r,c))
print('\n=== Locations of ATL_SUCCESS_REQ ===')
for r,c in locs:
    print(f'{get_column_letter(c)}{r}')

