arguments.command:
python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

wb = load_workbook('/root/data/workbook.xlsx', data_only=False, keep_vba=True, keep_links=True)
data = wb['Data']

# Search for year values 2019..2023
years = [2019,2020,2021,2022,2023]
locs = {y: [] for y in years}

for r in range(1, data.max_row+1):
    for c in range(1, data.max_column+1):
        v = data.cell(row=r, column=c).value
        if v in locs:
            locs[v].append((r,c))

for y in years:
    print(f'=== Locations of {y} (count {len(locs[y])}) ===')
    for r,c in locs[y][:30]:
        print(f'  {get_column_letter(c)}{r}')

# Also look for strings like '2019'
str_locs = []
for r in range(1, data.max_row+1):
    for c in range(1, data.max_column+1):
        v = data.cell(row=r, column=c).value
        if isinstance(v,str) and v.strip() in [str(y) for y in years]:
            str_locs.append((v.strip(), r,c))

print(f'\n=== Locations of string years (count {len(str_locs)}) ===')
for s,r,c in str_locs[:30]:
    print(f'  {s} at {get_column_letter(c)}{r}')

